-- SmartRide database: Integrated Public Transport and Cashless Payment System (Bacolod e-jeepneys)
-- Import this in phpMyAdmin (Import tab) or run: mysql -u root < smartride_db.sql
-- Demo accounts added for the presentation all use the password: smartride2026
--   admin: your existing "admin" account   driver: ramon   passenger: juandc

SET NAMES utf8mb4;
SET time_zone = '+08:00';
SET FOREIGN_KEY_CHECKS = 0;

DROP DATABASE IF EXISTS smartride_db;
CREATE DATABASE smartride_db CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE smartride_db;

CREATE TABLE roles (
  role_id    TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
  role_name  VARCHAR(20) NOT NULL,
  PRIMARY KEY (role_id),
  UNIQUE KEY uq_role_name (role_name)
) ENGINE=InnoDB;

CREATE TABLE users (
  user_id        INT UNSIGNED NOT NULL AUTO_INCREMENT,
  role_id        TINYINT UNSIGNED NOT NULL,
  full_name      VARCHAR(100) NOT NULL,
  email          VARCHAR(100) NOT NULL,
  phone          VARCHAR(20) NOT NULL,
  username       VARCHAR(50) NOT NULL,
  password_hash  VARCHAR(255) NOT NULL,
  status         ENUM('active','inactive') NOT NULL DEFAULT 'active',
  sms_alerts     TINYINT(1) NOT NULL DEFAULT 0,   -- 1 = text me through PhilSMS (the user turns it on)
  email_alerts   TINYINT(1) NOT NULL DEFAULT 0,   -- 1 = email me payment receipts through Gmail
  created_at     DATETIME NOT NULL,
  PRIMARY KEY (user_id),
  UNIQUE KEY uq_username (username),
  KEY fk_users_role (role_id),
  CONSTRAINT fk_users_role FOREIGN KEY (role_id) REFERENCES roles (role_id)
) ENGINE=InnoDB;

CREATE TABLE wallets (
  wallet_id   INT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id     INT UNSIGNED NOT NULL,
  qr_token    CHAR(32) NOT NULL,
  balance     DECIMAL(10,2) NOT NULL DEFAULT 0,
  status      ENUM('active','frozen') NOT NULL DEFAULT 'active',
  updated_at  DATETIME NOT NULL,
  PRIMARY KEY (wallet_id),
  UNIQUE KEY uq_wallet_user (user_id),
  CONSTRAINT fk_wallets_user FOREIGN KEY (user_id) REFERENCES users (user_id)
) ENGINE=InnoDB;

CREATE TABLE reloads (
  reload_id    INT UNSIGNED NOT NULL AUTO_INCREMENT,
  wallet_id    INT UNSIGNED NOT NULL,
  amount       DECIMAL(10,2) NOT NULL,
  method       ENUM('gcash','maya','store','kiosk','qrph') NOT NULL,
  reloaded_at  DATETIME NOT NULL,
  PRIMARY KEY (reload_id),
  KEY idx_reloads_wallet (wallet_id, reloaded_at),
  CONSTRAINT fk_reloads_wallet FOREIGN KEY (wallet_id) REFERENCES wallets (wallet_id)
) ENGINE=InnoDB;

CREATE TABLE routes (
  route_id     SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
  route_name   VARCHAR(100) NOT NULL,
  origin       VARCHAR(60) NOT NULL,
  destination  VARCHAR(60) NOT NULL,
  base_fare    DECIMAL(6,2) NOT NULL,
  PRIMARY KEY (route_id)
) ENGINE=InnoDB;

-- Landmarks along each route, from point A (seq 1) to point B (last seq).
-- Positions start approximate; with a Geoapify key, SmartRide looks each one up by name.
CREATE TABLE route_stops (
  stop_id     INT UNSIGNED NOT NULL AUTO_INCREMENT,
  route_id    SMALLINT UNSIGNED NOT NULL,
  seq         TINYINT UNSIGNED NOT NULL,
  name        VARCHAR(100) NOT NULL,
  latitude    DECIMAL(9,6) NOT NULL,
  longitude   DECIMAL(9,6) NOT NULL,
  geocoded    TINYINT(1) NOT NULL DEFAULT 0,      -- 1 = position came from Geoapify
  PRIMARY KEY (stop_id),
  KEY idx_stops_route (route_id, seq),
  CONSTRAINT fk_stops_route FOREIGN KEY (route_id) REFERENCES routes (route_id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- The road line for each route, from Geoapify routing (mode bus), saved so it's fetched once.
CREATE TABLE route_paths (
  route_id    SMALLINT UNSIGNED NOT NULL,
  points      MEDIUMTEXT NOT NULL,                -- JSON [[lat, lng], ...]
  meters      INT UNSIGNED NOT NULL,
  seconds     INT UNSIGNED NOT NULL,
  source      ENUM('geoapify','straight') NOT NULL,
  updated_at  DATETIME NOT NULL,
  PRIMARY KEY (route_id),
  CONSTRAINT fk_paths_route FOREIGN KEY (route_id) REFERENCES routes (route_id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE jeepneys (
  unit_id      SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
  operator_id  INT UNSIGNED NOT NULL,
  unit_code    VARCHAR(20) NOT NULL,
  plate_no     VARCHAR(20) NOT NULL,
  capacity     TINYINT UNSIGNED NOT NULL DEFAULT 25,
  status       ENUM('active','breakdown','offline') NOT NULL DEFAULT 'active',
  PRIMARY KEY (unit_id),
  UNIQUE KEY uq_unit_code (unit_code),
  CONSTRAINT fk_jeepneys_operator FOREIGN KEY (operator_id) REFERENCES users (user_id)
) ENGINE=InnoDB;

CREATE TABLE trips (
  trip_id     INT UNSIGNED NOT NULL AUTO_INCREMENT,
  unit_id     SMALLINT UNSIGNED NOT NULL,
  route_id    SMALLINT UNSIGNED NOT NULL,
  driver_id   INT UNSIGNED NOT NULL,
  started_at  DATETIME NOT NULL,
  ended_at    DATETIME NULL,
  PRIMARY KEY (trip_id),
  KEY idx_trips_driver (driver_id, started_at),
  KEY idx_trips_unit (unit_id, ended_at),
  CONSTRAINT fk_trips_unit FOREIGN KEY (unit_id) REFERENCES jeepneys (unit_id),
  CONSTRAINT fk_trips_route FOREIGN KEY (route_id) REFERENCES routes (route_id),
  CONSTRAINT fk_trips_driver FOREIGN KEY (driver_id) REFERENCES users (user_id)
) ENGINE=InnoDB;

-- One row per QR scan. A scan refused at full capacity is kept with its status.
CREATE TABLE fare_transactions (
  txn_id      INT UNSIGNED NOT NULL AUTO_INCREMENT,
  wallet_id   INT UNSIGNED NOT NULL,
  trip_id     INT UNSIGNED NOT NULL,
  amount      DECIMAL(6,2) NOT NULL,
  status      ENUM('paid','blocked_full','blocked_balance','blocked_frozen') NOT NULL,
  scanned_at  DATETIME NOT NULL,
  dest_stop_id    INT UNSIGNED NULL,              -- where the passenger is getting off
  arrival_sent_at DATETIME NULL,                  -- when the "arriving" SMS went out
  PRIMARY KEY (txn_id),
  KEY idx_fares_wallet (wallet_id, scanned_at),
  KEY idx_fares_trip (trip_id),
  KEY idx_fares_time (scanned_at),
  CONSTRAINT fk_fares_wallet FOREIGN KEY (wallet_id) REFERENCES wallets (wallet_id),
  CONSTRAINT fk_fares_trip FOREIGN KEY (trip_id) REFERENCES trips (trip_id),
  CONSTRAINT fk_fares_stop FOREIGN KEY (dest_stop_id) REFERENCES route_stops (stop_id) ON DELETE SET NULL
) ENGINE=InnoDB;

-- Camera counts: running totals for the trip.
CREATE TABLE passenger_logs (
  count_id    INT UNSIGNED NOT NULL AUTO_INCREMENT,
  trip_id     INT UNSIGNED NOT NULL,
  boarded     SMALLINT UNSIGNED NOT NULL,
  alighted    SMALLINT UNSIGNED NOT NULL,
  onboard     SMALLINT UNSIGNED NOT NULL,
  counted_at  DATETIME NOT NULL,
  PRIMARY KEY (count_id),
  KEY idx_logs_trip (trip_id, count_id),
  CONSTRAINT fk_plogs_trip FOREIGN KEY (trip_id) REFERENCES trips (trip_id)
) ENGINE=InnoDB;

CREATE TABLE gps_pings (
  ping_id      INT UNSIGNED NOT NULL AUTO_INCREMENT,
  unit_id      SMALLINT UNSIGNED NOT NULL,
  latitude     DECIMAL(9,6) NOT NULL,
  longitude    DECIMAL(9,6) NOT NULL,
  recorded_at  DATETIME NOT NULL,
  PRIMARY KEY (ping_id),
  KEY idx_gps_unit (unit_id, ping_id),
  CONSTRAINT fk_gps_unit FOREIGN KEY (unit_id) REFERENCES jeepneys (unit_id)
) ENGINE=InnoDB;

CREATE TABLE login_sessions (
  session_id  INT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id     INT UNSIGNED NOT NULL,
  login_at    DATETIME NOT NULL,
  logout_at   DATETIME NULL,
  PRIMARY KEY (session_id),
  KEY idx_sessions_user (user_id, login_at),
  CONSTRAINT fk_sessions_user FOREIGN KEY (user_id) REFERENCES users (user_id)
) ENGINE=InnoDB;

CREATE TABLE activity_logs (
  log_id     INT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id    INT UNSIGNED NULL,
  action     VARCHAR(40) NOT NULL,
  details    VARCHAR(255) NOT NULL DEFAULT '',
  logged_at  DATETIME NOT NULL,
  PRIMARY KEY (log_id),
  KEY idx_activity_action (action, log_id),
  CONSTRAINT fk_activity_user FOREIGN KEY (user_id) REFERENCES users (user_id) ON DELETE SET NULL
) ENGINE=InnoDB;

-- Maya Checkout reloads. One row per checkout a passenger starts.
-- The wallet is only credited after SmartRide asks Maya and Maya says PAYMENT_SUCCESS.
CREATE TABLE payments (
  payment_id    INT UNSIGNED NOT NULL AUTO_INCREMENT,
  wallet_id     INT UNSIGNED NOT NULL,
  amount        DECIMAL(10,2) NOT NULL,
  provider      ENUM('maya','demo') NOT NULL,
  reference_no  VARCHAR(36) NOT NULL,             -- our requestReferenceNumber, e.g. SR-15-a1b2c3
  checkout_id   VARCHAR(64) NULL,                 -- Maya's checkoutId (= paymentId)
  checkout_url  VARCHAR(500) NULL,                -- Maya's payment page
  status        ENUM('pending','paid','failed','expired','cancelled') NOT NULL DEFAULT 'pending',
  created_at    DATETIME NOT NULL,
  expires_at    DATETIME NOT NULL,
  paid_at       DATETIME NULL,
  PRIMARY KEY (payment_id),
  UNIQUE KEY uq_payments_ref (reference_no),
  UNIQUE KEY uq_payments_checkout (checkout_id),
  KEY idx_payments_wallet (wallet_id, created_at),
  CONSTRAINT fk_payments_wallet FOREIGN KEY (wallet_id) REFERENCES wallets (wallet_id)
) ENGINE=InnoDB;

-- Street names already looked up on Geoapify (so the free daily limit lasts).
CREATE TABLE geo_cache (
  lat_key     DECIMAL(8,4) NOT NULL,
  lng_key     DECIMAL(8,4) NOT NULL,
  address     VARCHAR(255) NOT NULL,
  created_at  DATETIME NOT NULL,
  PRIMARY KEY (lat_key, lng_key)
) ENGINE=InnoDB;

-- Forgot-password links. Only a SHA-256 hash of the token is saved, never the token itself.
CREATE TABLE password_resets (
  reset_id    INT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id     INT UNSIGNED NOT NULL,
  token_hash  CHAR(64) NOT NULL,
  created_at  DATETIME NOT NULL,
  expires_at  DATETIME NOT NULL,
  used_at     DATETIME NULL,
  PRIMARY KEY (reset_id),
  UNIQUE KEY uq_resets_token (token_hash),
  KEY idx_resets_user (user_id, created_at),
  CONSTRAINT fk_resets_user FOREIGN KEY (user_id) REFERENCES users (user_id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- Alerts shown in the app and sent out by push (OneSignal), SMS (PhilSMS) and email (Gmail).
CREATE TABLE notifications (
  notif_id    INT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id     INT UNSIGNED NOT NULL,
  type        VARCHAR(30) NOT NULL,       -- fare_paid, fare_blocked, low_balance, reload, unit_full, ...
  title       VARCHAR(100) NOT NULL,
  body        VARCHAR(255) NOT NULL DEFAULT '',
  link        VARCHAR(100) NOT NULL DEFAULT '',
  is_read     TINYINT(1) NOT NULL DEFAULT 0,
  created_at  DATETIME NOT NULL,
  PRIMARY KEY (notif_id),
  KEY idx_notifications_user (user_id, notif_id),
  CONSTRAINT fk_notifications_user FOREIGN KEY (user_id) REFERENCES users (user_id) ON DELETE CASCADE
) ENGINE=InnoDB;

